SELECT r.id, r.user_id, r.username, r.avatar, r.product_id, r.order_id, r.rating, r.rating_desc, r.rating_logistics, r.rating_service, r.content, r.images, r.is_followup, r.like_count, r.comment_count, r.create_time, p.name AS product_name, p.main_image AS product_image FROM review r LEFT JOIN product p ON r.product_id = p.id WHERE r.is_followup = 0
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND r.username LIKE CONCAT('%', #{username}, '%')
AND r.rating = #{rating}
AND r.create_time >= #{startDate}
AND r.create_time <= #{endDate}
AND r.images IS NOT NULL AND r.images != '' AND r.images != '[]'
AND (r.images IS NULL OR r.images = '' OR r.images = '[]')
AND EXISTS (SELECT 1 FROM review f WHERE f.order_id = r.order_id AND f.product_id = r.product_id AND f.is_followup = 1)
AND NOT EXISTS (SELECT 1 FROM review f WHERE f.order_id = r.order_id AND f.product_id = r.product_id AND f.is_followup = 1)
ORDER BY r.like_count DESC, r.create_time DESC ORDER BY r.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM review r LEFT JOIN product p ON r.product_id = p.id WHERE r.is_followup = 0
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND r.username LIKE CONCAT('%', #{username}, '%')
AND r.rating = #{rating}
AND r.create_time >= #{startDate}
AND r.create_time <= #{endDate}
AND r.images IS NOT NULL AND r.images != '' AND r.images != '[]'
AND (r.images IS NULL OR r.images = '' OR r.images = '[]')
AND EXISTS (SELECT 1 FROM review f WHERE f.order_id = r.order_id AND f.product_id = r.product_id AND f.is_followup = 1)
AND NOT EXISTS (SELECT 1 FROM review f WHERE f.order_id = r.order_id AND f.product_id = r.product_id AND f.is_followup = 1)
